import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import './Education.css';

const educationData = [
  {
    id: 1,
    period: "2024 - 2028",
    status: "Active",
    degree: "B.Tech in Artificial Intelligence & Data Science",
    institution: "Vishwakarma Institute of Technology, Pune",
    gradient: "from-indigo-500 via-purple-500 to-pink-500",
    shadowColor: "rgba(139, 92, 246, 0.5)",
    icon: "🎓",
    details: [
      "Specializing in Machine Learning & Neural Networks.",
      "Comprehensive coursework in Data Analytics.",
      "Hands-on Software Development & Full Stack projects."
    ],
    tags: ["AI", "Data Science", "React", "Node.js"]
  },
  {
    id: 2,
    period: "2022 - 2024",
    status: "Completed",
    degree: "Higher Secondary Education (PCM)",
    institution: "HRSPM & Vision Academy",
    gradient: "from-cyan-400 via-blue-500 to-indigo-600",
    shadowColor: "rgba(6, 182, 212, 0.5)",
    icon: "🔬",
    details: [
      "Intensive focus on Physics, Chemistry, and Mathematics.",
      "Successfully qualified for JEE Advanced.",
      "Built a rock-solid foundation for advanced engineering."
    ],
    tags: ["Physics", "Mathematics", "Analytical Thinking"]
  }
];

const Education = () => {
  const [activeCard, setActiveCard] = useState(null);

  // Parent container variants
  const staggerContainer = {
    hidden: { opacity: 0 },
    show: {
      opacity: 1,
      transition: {
        staggerChildren: 0.3,
        delayChildren: 0.2
      }
    }
  };

  return (
    <section id="education" className="edu-crazy-section">
      {/* Dynamic Background Particles */}
      <div className="edu-particles-container">
        {[...Array(15)].map((_, i) => (
          <div key={i} className={`edu-particle particle-${i + 1}`}></div>
        ))}
      </div>

      <div className="container relative z-10">
        <motion.div
          className="edu-crazy-header"
          initial={{ opacity: 0, y: -50 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: "-100px" }}
          transition={{ duration: 0.8, type: "spring" }}
        >
          <div className="glitch-wrapper">
            <h2 className="edu-glitch-title" data-text="EDUCATION">EDUCATION</h2>
          </div>
          <p className="edu-crazy-subtitle">My Academic Evolution</p>
        </motion.div>

        <motion.div
          className="edu-crazy-grid"
          variants={staggerContainer}
          initial="hidden"
          whileInView="show"
          viewport={{ once: true, margin: "-50px" }}
        >
          {educationData.map((edu, index) => (
            <motion.div
              key={edu.id}
              className={`edu-holographic-card ${activeCard === edu.id ? 'active' : ''}`}
              onMouseEnter={() => setActiveCard(edu.id)}
              onMouseLeave={() => setActiveCard(null)}
              initial={{ opacity: 0, scale: 0.8, rotateX: 20 }}
              whileInView={{ opacity: 1, scale: 1, rotateX: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.6, type: "spring", bounce: 0.4 }}
              style={{ '--shadow-color': edu.shadowColor }}
            >
              <div className="card-glass-pane">
                <div className="card-header-glow"></div>

                <div className="edu-card-top">
                  <div className="edu-icon-3d">{edu.icon}</div>
                  <div className="edu-badge">{edu.period}</div>
                </div>

                <h3 className="edu-degree-text">{edu.degree}</h3>
                <h4 className="edu-inst-text">{edu.institution}</h4>

                <div className="edu-details-box">
                  <ul>
                    {edu.details.map((detail, i) => (
                      <motion.li
                        key={i}
                        initial={{ opacity: 0, x: -10 }}
                        animate={{ opacity: 1, x: 0 }}
                        transition={{ delay: 0.4 + (i * 0.1) }}
                      >
                        <i className="fas fa-check-circle"></i> {detail}
                      </motion.li>
                    ))}
                  </ul>
                </div>

                <div className="edu-tags-cloud">
                  {edu.tags.map((tag, i) => (
                    <span key={i} className="edu-tech-tag">{tag}</span>
                  ))}
                </div>

                {/* Moving border overlay */}
                <div className="moving-border-overlay"></div>
              </div>
            </motion.div>
          ))}
        </motion.div>
      </div>
    </section>
  );
};

export default Education;
